&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;التحديثات وعمليات الترحيل لعدة نسخ متماثلة&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;التحديثات وعمليات الترحيل لعدة نسخ متماثلة&lt;/a&gt;
&lt;/span&gt;
