  &lt;a href=&#34;#%d8%a7%d9%84%d9%85%d8%b5%d8%a7%d8%af%d8%b1&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;المصادر&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;


































































































































